function assertEqual(actual, expected, name) {
  if (actual === expected) {
    console.log('PASS: ' + name);
  } else {
    console.log('FAIL: ' + name);
  }
}

assertEqual(2 + 2, 4, 'addition');
assertEqual('hi'.length, 2, 'string length');
assertEqual([1, 2].length, 3, 'array length');

